llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "In humans, ginsenoside Rg3—the closest analogue sharing the same dammarane aglycone and C3 disaccharide—showed low oral bioavailability; the query's additional C20 disaccharide increases size and polarity, making absorption no better.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Glycyrrhizin, a triterpene glycoside with two sugar moieties, had an absolute oral bioavailability of only about 0.25% in humans, demonstrating that large triterpene glycosides are very poorly absorbed as intact molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Astragaloside IV, another triterpene saponin with multiple sugars, had poor oral bioavailability in humans due to very low solubility in biological fluids, a liability shared by the heavily glycosylated query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "A polyglycosylated steroidal glycoside showed low oral bioavailability in human participants, supporting the general pattern that heavily glycosylated natural products are poorly absorbed orally.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large bisdesmosidic triterpene glycoside (ginsenoside Rb1-like). The closest analogue Rg3 has low human oral bioavailability, and other polyglycosylated triterpene/steroid glycosides such as glycyrrhizin, astragaloside IV, and avenacoside-related compounds are also poorly absorbed. The additional C20 disaccharide increases molecular weight and polarity, making F >= 20% unlikely.",
  "evidence_gaps": [
    "No quantitative absolute F value is available for the query or Rg3; the Rg3 record is qualitative low bioavailability.",
    "Gut-microbial hydrolysis to aglycone metabolites may occur, but absorption of the intact parent glycoside is expected to be low.",
    "No direct human pharmacokinetic study for ginsenoside Rb1 was retrieved in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

